namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious traditional Italian pizza with fresh basil and mozzarella.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = [
                "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until the crust is golden.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            ],
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
            Steps = [
                "Cook spaghetti in salted boiling water until al dente.",
                "Fry pancetta in a large pan until crispy.",
                "Whisk eggs with grated Pecorino and plenty of black pepper.",
                "Drain pasta, reserving some cooking water.",
                "Toss hot pasta with pancetta, then remove from heat.",
                "Stir in the egg mixture quickly, adding pasta water to create a creamy sauce."
            ],
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
            Steps = [
                "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                "Grill or broil the chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in a large pan.",
                "Add spices, tomato sauce, and simmer for 15 minutes.",
                "Stir in heavy cream and the cooked chicken.",
                "Simmer for 10 more minutes and serve with rice or naan."
            ],
            Ratings = [5, 4, 5, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Description = "A vibrant stir-fried noodle dish with vegetables, tofu, and a tangy sauce.",
            Ingredients = ["Rice noodles", "Firm tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Eggs"],
            Steps = [
                "Soak rice noodles in warm water for 20 minutes, then drain.",
                "Press and cube tofu, then pan-fry until golden.",
                "Mix tamarind paste, fish sauce, sugar, and lime juice for the sauce.",
                "Stir-fry vegetables in a hot wok for 2 minutes.",
                "Add noodles and sauce, toss until well coated.",
                "Push noodles aside, scramble eggs in the wok, then mix everything.",
                "Serve topped with crushed peanuts and lime wedges."
            ],
            Ratings = [4, 4, 5]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
            Steps = [
                "Brown ground beef with diced onion in a skillet.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm taco shells in the oven for 3 minutes.",
                "Fill shells with seasoned beef.",
                "Top with shredded lettuce, diced tomato, cheese, and sour cream."
            ],
            Ratings = [4, 3, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Classic French Onion Soup", Category = "French",
            Description = "Deeply caramelized onions in a rich beef broth topped with melted Gruyère.",
            Ingredients = ["Yellow onions", "Butter", "Beef broth", "Dry white wine", "Thyme", "Bay leaf", "Baguette slices", "Gruyère cheese"],
            Steps = [
                "Slice onions thinly and cook in butter over medium-low heat for 45 minutes.",
                "Add wine and cook until evaporated.",
                "Add beef broth, thyme, and bay leaf; simmer for 20 minutes.",
                "Ladle soup into oven-safe bowls.",
                "Top with baguette slices and shredded Gruyère.",
                "Broil until cheese is bubbly and golden."
            ],
            Ratings = [5, 5, 4, 5]
        },
        new()
        {
            Id = 7, Title = "Green Curry with Shrimp", Category = "Thai",
            Description = "Aromatic Thai green curry with plump shrimp and vegetables in coconut milk.",
            Ingredients = ["Shrimp", "Green curry paste", "Coconut milk", "Bamboo shoots", "Thai basil", "Bell pepper", "Fish sauce", "Sugar", "Jasmine rice"],
            Steps = [
                "Heat a splash of coconut milk in a pan until it separates.",
                "Fry green curry paste in the oil for 1 minute.",
                "Add remaining coconut milk and bring to a simmer.",
                "Add bamboo shoots and bell pepper, cook for 5 minutes.",
                "Add shrimp and cook until pink, about 3 minutes.",
                "Season with fish sauce and sugar, stir in Thai basil.",
                "Serve over steamed jasmine rice."
            ],
            Ratings = [5, 4]
        },
        new()
        {
            Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = [
                "Preheat oven to 425°F (220°C). Grease and flour ramekins.",
                "Melt chocolate and butter together, then let cool slightly.",
                "Whisk eggs, sugar, and vanilla until thick and pale.",
                "Fold chocolate mixture into the eggs, then fold in flour.",
                "Divide batter among ramekins.",
                "Bake for 12–14 minutes until edges are set but center jiggles.",
                "Invert onto plates and serve immediately."
            ],
            Ratings = [5, 5, 5, 4, 5]
        }
    ];

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

