﻿@page "/"
@using RecipeCommunity.Services

@inject RecipeService Recipes

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<h2 class="mb-3">Browse by Category</h2>

<div class="row">
    @foreach (var category in Recipes.GetCategories())
    {
        var recipes = Recipes.GetByCategory(category);
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h4 class="card-title">@CategoryEmoji(category) @category</h4>
                    <p class="text-muted">@recipes.Count recipe(s)</p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse &rarr;</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "French" => "🇫🇷",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

