@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                            <span class="text-warning">
                                @if (recipe.AverageRating > 0)
                                {
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        <span>@(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                    }
                                    <span class="text-muted ms-1">(@recipe.AverageRating)</span>
                                }
                                else
                                {
                                    <span class="text-muted">No ratings yet</span>
                                }
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-danger">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.Ratings.Count" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🥕 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@using RecipeCommunity.Services

@rendermode InteractiveServer

@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe</PageTitle>

<h1>📤 Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "<strong>@title</strong>" has been submitted.
        <a href="category/@category">View it here</a>.
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="title" placeholder="e.g. Grandma's Apple Pie" required />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="category" required>
                <option value="">-- Select a category --</option>
                @foreach (var cat in Recipes.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label" for="description">Short Description</label>
            <InputTextArea id="description" class="form-control" @bind-Value="description" rows="2"
                           placeholder="A brief description of the dish" required />
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="ingredientsText" rows="5"
                           placeholder="One ingredient per line" required />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="stepsText" rows="6"
                           placeholder="One step per line" required />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string description = string.Empty;
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))
            return;

        var ingredients = ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        Recipes.AddRecipe(title, category, description, ingredients, steps);
        submitted = true;
    }
}

@using RecipeCommunity.Services

@rendermode InteractiveServer

@inject RecipeService Recipes

<div class="star-rating d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= hoverStar ? "star-hover" : star <= Math.Round(CurrentRating) ? "star-filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverStar = star"
              @onmouseout="() => hoverStar = 0"
              role="button"
              title="Rate @star star(s)">
            @(star <= (hoverStar > 0 ? hoverStar : Math.Round(CurrentRating)) ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted small">
        @if (userRated)
        {
            <span>Thanks for rating!</span>
        }
        else if (RatingCount > 0)
        {
            <span>@CurrentRating / 5 (@RatingCount ratings)</span>
        }
        else
        {
            <span>Be the first to rate!</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverStar;
    private bool userRated;

    private void Rate(int stars)
    {
        Recipes.AddRating(RecipeId, stars);
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.Ratings.Count;
        }
        userRated = true;
    }
}

