        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="stepsText" rows="6"
                           placeholder="One step per line" required />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string description = string.Empty;
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))
            return;

        var ingredients = ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        Recipes.AddRecipe(title, category, description, ingredients, steps);
        submitted = true;
    }
}

@using RecipeCommunity.Services

@rendermode InteractiveServer

@inject RecipeService Recipes

<div class="star-rating d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= hoverStar ? "star-hover" : star <= Math.Round(CurrentRating) ? "star-filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverStar = star"
              @onmouseout="() => hoverStar = 0"
              role="button"
              title="Rate @star star(s)">
            @(star <= (hoverStar > 0 ? hoverStar : Math.Round(CurrentRating)) ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted small">
        @if (userRated)
        {
            <span>Thanks for rating!</span>
        }
        else if (RatingCount > 0)
        {
            <span>@CurrentRating / 5 (@RatingCount ratings)</span>
        }
        else
        {
            <span>Be the first to rate!</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverStar;
    private bool userRated;

    private void Rate(int stars)
    {
        Recipes.AddRating(RecipeId, stars);
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.Ratings.Count;
        }
        userRated = true;
    }
}

